metrics=json.loads((Q/'qa-metrics.json').read_text());registration=json.loads((Q/'material-registration-proof.json').read_text());frames=[];edges=[]
for p in P:
 im=Image.open(R/p/'master.png');a=np.array(im);m=a[:,:,3]>=128;m[800:]=False;ll,n=label(m);cs=[]
